INSERT INTO producto (categoria_id, nombre, slug, precio, existencias, stock_minimo, modelo_codigo, especificaciones, descripcion)
SELECT c.id, 'Procesador Intel Core Ultra 9 285K', 'procesador-intel-core-ultra-9-285k', 11999, 3, 1, 'cpu-core-ultra-9-285k', '[["Núcleos / hilos", "24 (8P + 16E) / 24"], ["Frecuencia máxima", "5.7 GHz"], ["Caché L3", "36 MB"], ["Socket", "LGA1851"], ["Potencia base", "125 W"], ["Memoria", "DDR5"], ["Gráficos", "Integrados"]]'::jsonb, 'Tope de gama para crear contenido y jugar: 24 núcleos y NPU para tareas de IA.'
